<?php
declare(strict_types=1);
function index():void{require_login();require_can('pages.edit');admin_view('pages-index',['title'=>'Page contents','rows'=>db_all('SELECT p.*,COUNT(s.id) section_count,SUM(s.enabled=1) enabled_count FROM pages p LEFT JOIN page_sections s ON s.page_id=p.id GROUP BY p.id ORDER BY p.sort,p.name')]);}
function edit(string $id):void{require_login();require_can('pages.edit');$page=db_one('SELECT * FROM pages WHERE id=?',[(int)$id]);if(!$page){http_response_code(404);admin_view('error',['code'=>404,'title'=>'Page not found','message'=>'That page does not exist.']);return;}admin_view('pages-form',['title'=>'Edit '.$page['name'],'page'=>$page,'sections'=>db_all('SELECT * FROM page_sections WHERE page_id=? ORDER BY sort,id',[(int)$id]),'media'=>db_all("SELECT id,path,alt FROM media WHERE alt<>'' ORDER BY created_at DESC")]);}
function update(string $id):never{require_login();require_can('pages.edit');$page=db_one('SELECT * FROM pages WHERE id=?',[(int)$id]);if(!$page){flash('error','Page not found.');redirect(admin_url('pages'));}$title=(string)input('title','');$meta=(string)input('meta_description','');if(mb_strlen($meta)>255){flash('error','Meta description must be 255 characters or fewer.');redirect(admin_url('pages/'.$id));}$u=current_user();db_update('pages',(int)$id,['title'=>$title,'meta_description'=>$meta,'og_image_id'=>(int)input('og_image_id','0')?:null,'updated_at'=>now(),'updated_by'=>$u['id']]);foreach(db_all('SELECT id,section_key FROM page_sections WHERE page_id=?',[(int)$id]) as $s){$raw=(string)($_POST['section_data'][$s['id']]??'');json_decode($raw,true);if(json_last_error()!==JSON_ERROR_NONE){flash('error','Invalid JSON in '.$s['section_key'].': '.json_last_error_msg());redirect(admin_url('pages/'.$id));}db_update('page_sections',(int)$s['id'],['data'=>$raw,'sort'=>(int)($_POST['section_sort'][$s['id']]??0),'enabled'=>isset($_POST['section_enabled'][$s['id']])?1:0,'updated_at'=>now(),'updated_by'=>$u['id']]);}log_activity('updated','page',$id,'Updated '.$page['name']);flash('success','Page content saved.');redirect(admin_url('pages/'.$id));}
